<div class="bg-white border rounded-xl overflow-hidden"><table class="w-full text-sm" id="lines"><thead class="bg-gray-50"><tr><th class="p-3">Description</th><th>Qty</th><th>Unit price</th><th>Discount</th><th>GST %</th><th></th></tr></thead><tbody>@php $rows=old('items',$invoice->exists?$invoice->lines->map(fn($l)=>['description'=>$l->description,'quantity'=>$l->quantity,'unit_price'=>$l->unit_price_minor/100,'discount'=>$l->discount_minor/100,'tax_rate'=>$l->tax_rate_basis_points/100,'product_id'=>$l->product_id])->all():[['description'=>'','quantity'=>1,'unit_price'=>0,'discount'=>0,'tax_rate'=>10]]); @endphp @foreach($rows as $i=>$row)<tr class="border-t item-row"><td class="p-2"><input name="items[{{ $i }}][description]" value="{{ $row['description'] }}" required class="w-full border rounded p-2"></td><td><input type="number" step="0.0001" name="items[{{ $i }}][quantity]" value="{{ $row['quantity'] }}" class="w-24 border rounded p-2"></td><td><input type="number" step="0.01" name="items[{{ $i }}][unit_price]" value="{{ $row['unit_price'] }}" class="w-28 border rounded p-2"></td><td><input type="number" step="0.01" name="items[{{ $i }}][discount]" value="{{ $row['discount'] }}" class="w-24 border rounded p-2"></td><td><input type="number" step="0.01" name="items[{{ $i }}][tax_rate]" value="{{ $row['tax_rate'] }}" class="w-20 border rounded p-2"></td><td><button type="button" onclick="this.closest('tr').remove()" class="text-red-600">Remove</button></td></tr>@endforeach</tbody></table><button type="button" id="add-line" class="m-4 px-3 py-2 border rounded-lg">Add line</button></div>
<div class="bg-white border rounded-xl p-5"><label>Customer message<textarea name="customer_message" class="mt-1 w-full border rounded-lg p-2">{{ old('customer_message',$invoice->customer_message) }}</textarea></label><label class="block mt-3">Internal notes<textarea name="notes" class="mt-1 w-full border rounded-lg p-2">{{ old('notes',$invoice->notes) }}</textarea></label></div><div class="flex justify-end"><button class="px-5 py-3 bg-purple-600 text-white rounded-lg">Save draft</button></div></form></main><script>document.getElementById('add-line').onclick=()=>{const b=document.querySelector('#lines tbody'),i=b.children.length;const r=b.children[0].cloneNode(true);r.querySelectorAll('input').forEach(x=>{x.name=x.name.replace(/items\[\d+\]/,`items[${i}]`);if(x.name.includes('description'))x.value='';});b.appendChild(r);};</script>@endsection